create table if not exists events (id bigint generated by default as identity primary key, title text not null, slug text unique not null, description text not null, artist text, venue text not null, starts_at timestamptz not null, image_url text, status text not null default 'PUBLISHED', created_at timestamptz not null default now());
create table if not exists ticket_types (id bigint generated by default as identity primary key, event_id bigint references events(id) on delete cascade, name text not null, price_cents integer not null check(price_cents >= 0), total_supply integer not null check(total_supply > 0), available_supply integer not null, unique(event_id,name));
create table if not exists orders (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), status text not null default 'PENDING', total_cents integer not null, wallet_address text, transaction_hash text, created_at timestamptz not null default now());
create table if not exists tickets (id uuid primary key default gen_random_uuid(), order_id uuid references orders(id), ticket_type_id bigint references ticket_types(id), ticket_code text unique not null, qr_payload text not null, status text not null default 'VALID', token_id bigint, created_at timestamptz not null default now());
create table if not exists listings (id uuid primary key default gen_random_uuid(), ticket_id uuid unique references tickets(id), seller_wallet text not null, price_cents integer not null check(price_cents > 0), status text not null default 'ACTIVE', created_at timestamptz not null default now());
create table if not exists check_ins (id uuid primary key default gen_random_uuid(), ticket_id uuid unique references tickets(id), checked_in_by uuid references auth.users(id), checked_in_at timestamptz not null default now());
alter table events enable row level security; alter table ticket_types enable row level security; alter table tickets enable row level security; alter table listings enable row level security;
create policy "public can view published events" on events for select using (status='PUBLISHED');
create policy "public can view ticket types" on ticket_types for select using (true);
create policy "public can view active listings" on listings for select using (status='ACTIVE');
